import 'package:flutter/material.dart';import '../services/storage_service.dart';class BriefScreen extends StatelessWidget{const BriefScreen({super.key});@override Widget build(BuildContext c){final cs=StorageService.commitments(),es=StorageService.employees();final overdue=cs.where((x)=>x.status=='pending'&&x.dueDate.isBefore(DateTime.now())).fold(0.0,(s,x)=>s+(x.amount??0));final adv=es.fold(0.0,(s,e)=>s+e.totalAdvances);return Scaffold(appBar:AppBar(title:const Text('بريف الأسبوع')),body:Padding(padding:const EdgeInsets.all(16),child:Card(child:Padding(padding:const EdgeInsets.all(16),child:Text('الالتزامات: ${cs.length}\nالعاملون: ${es.length}\nالمتأخرات المالية: ${overdue.toStringAsFixed(0)} جنيه\nإجمالي السلف: ${adv.toStringAsFixed(0)} جنيه\n\nهذا ملخص حسابي للبيانات المحلية.')))));}}
